NOTES: we have defaults in SecretsLoader that are possible to override from ENV.

{noformat}if (!secrets.loader.order) {
    secrets.loader.order = [
        SecretsStorageType.ENVIRONMENT,
        (process.env.SECRETS_STORAGE_TYPE as SecretsStorageType) ||
            (config.environment === Environment.LOCAL ? SecretsStorageType.FILE : SecretsStorageType.S3)
    ];
}

const fileStorageFileName = `${environment}.secrets.json`;

const fileStoragePath = NodeSetupConfigBuilder.getFileStoragePath(
    sourceLocationInfo?.project_dir_path,
    fileStorageFileName
);
secrets.loader.directory = {
    storage_path: process.env.SECRETS_LOADER_DIR_PATH || fileStoragePath,
    storage_name: process.env.SECRETS_LOADER_DIR_NAME || `secrets.${environment}`,
    ...secrets.loader.directory
};
secrets.loader.file = {
    storage_path: process.env.SECRETS_LOADER_FILE_PATH || fileStoragePath,
    storage_file: process.env.SECRETS_LOADER_FILE_NAME || fileStorageFileName,
    ...secrets.loader.file
};
secrets.loader.environment = {
    env_var_prefix: process.env.SECRETS_LOADER_ENV_PREFIX || `secrets-${environment}-`,
    ...secrets.loader.environment
};
secrets.loader.s3 = {
    region: process.env.SECRETS_LOADER_S3_REGION || "eu-central-1",
    root_path: process.env.SECRETS_LOADER_S3_PATH || environment,
    root_bucket: process.env.SECRETS_LOADER_S3_BUCKET || "bolt-vault",
    ...secrets.loader.s3
};
if (!secrets.base_path) {
    secrets.base_path = process.env.SECRETS_BASE_PATH || "server";
}{noformat}

Also, the ENV secrets storage is always added as first storage, thus its possible to override ANY secret from ENV as well

